sed -i 's/                            Text(msg.text, color = if(isMe) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurface)/                            Text(msg.text, color = if(isMe) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurface)\n\n                            val timeStr = try {\n                                if (msg.createdAt.isNotBlank() \&\& msg.createdAt.contains("T")) {\n                                    val format = java.text.SimpleDateFormat("yyyy-MM-dd'"'"'T'"'"'HH:mm:ss", java.util.Locale.getDefault())\n                                    format.timeZone = java.util.TimeZone.getTimeZone("UTC")\n                                    val cleanTime = if (msg.createdAt.contains(".")) msg.createdAt.substringBefore(".") else msg.createdAt.replace("Z", "")\n                                    val date = format.parse(cleanTime)\n                                    if (date != null) {\n                                        val outFormat = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault())\n                                        outFormat.format(date)\n                                    } else {\n                                        msg.createdAt.substringAfter("T").take(5)\n                                    }\n                                } else ""\n                            } catch (e: Exception) {\n                                ""\n                            }\n\n                            if (timeStr.isNotBlank()) {\n                                Text(\n                                    text = timeStr,\n                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = androidx.compose.ui.unit.sp(10)),\n                                    color = if (isMe) MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.7f) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),\n                                    modifier = Modifier.align(Alignment.End).padding(top = 2.dp)\n                                )\n                            }/g' app/src/main/java/com/strangerhelp/app/ui/screens/chat/ChatDetailScreen.kt
